}

function ConfirmDeleteDialog({ open, imageName, onCancel, onConfirm }) {
  const cancelRef = useRef(null);

  useEffect(() => {
    if (!open) return;
    const onKey = (e) => {
      if (e.key === "Escape") onCancel();
    };
    document.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    cancelRef.current?.focus();
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [open, onCancel]);

  if (!open) return null;

  return (
    <div
      className="modal-overlay"
      onClick={onCancel}
      role="presentation"
    >
      <div
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="confirm-title"
        aria-describedby="confirm-desc"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="modal-body">
          <div className="modal-icon" aria-hidden="true">
            <Icon name="alert" />
          </div>
          <div className="modal-text">
            <h2 id="confirm-title">Delete image?</h2>
            <p id="confirm-desc">
              <strong>{imageName}</strong> will be permanently removed
              from your library. This action cannot be undone.
            </p>
          </div>
        </div>
        <div className="modal-footer">
          <button
            ref={cancelRef}
            type="button"
            className="btn"
            onClick={onCancel}
          >
            Cancel
          </button>
          <button
            type="button"
            className="btn btn-danger-solid"
            onClick={onConfirm}
            autoFocus
          >
            <Icon name="trash" />
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}

function ImagePreviewPage() {
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const triggerRef = useRef(null);

  const imageName = "alpine-vista.jpg";

  const handleConfirm = useCallback(() => {
    setDeleted(true);
    setDialogOpen(false);
  }, []);

  const handleCancel = useCallback(() => {
    setDialogOpen(false);
    setTimeout(() => triggerRef.current?.focus(), 0);
  }, []);

  return (
    <div className="page">
      <div className="page-header">
        <nav className="breadcrumbs" aria-label="Breadcrumb">
          <a href="#">Library</a>
          <span className="sep">/</span>
          <a href="#">Landscapes</a>
          <span className="sep">/</span>
          <span>{imageName}</span>
        </nav>
      </div>

      <div className="preview-card">
        <div className="preview-image-wrap">
          {deleted ? (
            <div style={{ color: "var(--text-muted)", fontSize: 14 }}>
              Image deleted from your library.
            </div>
          ) : (
            <MountainsArt />
          )}
        </div>

        <div className="preview-meta">
          <div className="preview-info">
            <h1>{imageName}</h1>
            <p>2400 × 1500 · 1.8 MB · Added Apr 12</p>
          </div>
          <div className="preview-actions">
            <button type="button" className="btn" disabled={deleted}>
              <Icon name="download" />
              Download
            </button>
            <button
              ref={triggerRef}
              type="button"
              className="trigger btn btn-danger"
              onClick={() => setDialogOpen(true)}
              disabled={deleted}
              aria-haspopup="dialog"
              aria-expanded={dialogOpen}
            >
              <Icon name="trash" />
              Delete
            </button>
          </div>
        </div>
      </div>

      <ConfirmDeleteDialog
        open={dialogOpen}
        imageName={imageName}
        onCancel={handleCancel}
        onConfirm={handleConfirm}
      />
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<ImagePreviewPage />);

