* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI",
               Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

.page {
  max-width: 880px;
  margin: 0 auto;
  padding: 48px 24px 96px;
}

.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
}

.breadcrumbs {
  font-size: 13px;
  color: var(--text-muted);
  letter-spacing: 0.02em;
}
.breadcrumbs a { color: var(--text-dim); text-decoration: none; }
.breadcrumbs a:hover { color: var(--text); }
.breadcrumbs .sep { margin: 0 8px; opacity: 0.5; }

.preview-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: var(--shadow);
}

.preview-image-wrap {
  position: relative;
  aspect-ratio: 16 / 10;
  background:
    radial-gradient(ellipse at 30% 20%, #2c3e63 0%, transparent 55%),
    radial-gradient(ellipse at 75% 80%, #4a2a55 0%, transparent 55%),
    linear-gradient(135deg, #11151b 0%, #1a2030 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.preview-image-wrap::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 45%, rgba(255,255,255,0.04) 0%, transparent 60%);
  pointer-events: none;
}

.preview-mountains {
  width: 100%;
  height: 100%;
  display: block;
}

.preview-meta {
  padding: 18px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid var(--border);
}

.preview-info h1 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.preview-info p {
  margin: 0;
  font-size: 13px;
  color: var(--text-muted);
}

.preview-actions {
  display: flex;
  gap: 10px;
}

.btn {
  appearance: none;
  border: 1px solid var(--border-strong);
  background: var(--bg-card);
  color: var(--text);
  padding: 9px 14px;
  font-size: 13.5px;
  font-weight: 500;
  border-radius: 8px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: background 0.15s ease, border-color 0.15s ease,
              transform 0.05s ease, color 0.15s ease;
  font-family: inherit;
}
.btn:hover { background: #222932; border-color: #3a4452; }
.btn:active { transform: translateY(1px); }
.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.btn-danger {
  background: var(--danger-bg);
  border-color: rgba(229, 72, 77, 0.35);
  color: #ff8a8e;
}
.btn-danger:hover {
  background: rgba(229, 72, 77, 0.2);
  border-color: rgba(229, 72, 77, 0.55);
