  align-items: center;
  justify-content: center;
  color: var(--danger-hover);
}

.modal-text h2 {
  margin: 0 0 6px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.modal-text p {
  margin: 0;
  font-size: 13.5px;
  line-height: 1.5;
  color: var(--text-dim);
}
.modal-text strong { color: var(--text); font-weight: 600; }

.modal-footer {
  padding: 18px 22px 20px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 520px) {
  .preview-meta { flex-direction: column; align-items: stretch; }
  .preview-actions { justify-content: flex-end; }
}
